<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mcolormatchstd extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY . "mcolormatchstdmodel");        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $this->limit = LIMITPERPAGE;    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarHashId = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if ($VarHashId <> '') {            $VarId = base64_decode(urldecode($VarHashId));            $ArrResults = $this->mcolormatchstdmodel->fnGetInfo('', '', $VarId);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditcolormatch', $ArrData);    }    public function updateInfo() {        $ArrResult = [];        $VarUserInfo = fnGetUserLoggedInfo(1);        $VarCompanyId = $VarUserInfo['companyid'];        $VarColorMatchStd = xssclean($this->input->post('cms'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarColorMatchStd <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $VarCompanyId, 'clrmatchingstd' => $VarColorMatchStd,                'status' => $VarStatus, 'updatedby' => $VarUserInfo['id'], 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mcolormatchstdmodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manage() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarColormatchstd = xssclean($this->input->post('cms'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('c.colormatchstd', 'c.status', 'contactname', 'c.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mcolormatchstd/manage';            $config['total_rows'] = $this->mcolormatchstdmodel->fnCount($VarColormatchstd, $VarStatus);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "c.dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrFabricTypeList = $this->mcolormatchstdmodel->fnList($VarColormatchstd, $VarStatus, $this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Colormatchstd');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrFabricTypeList as $ObjFabric) {                $ArrFnlList[$i]['id'] = $ObjFabric->id;                $ArrFnlList[$i]['cms'] = $ObjFabric->clrmatchingstd;                $ArrFnlList[$i]['ub'] = $ObjFabric->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjFabric->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjFabric->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managecolormatchstd');        }    }    function changemStatus() {        $VarActDeactOption = xssclean($this->input->post('actdeactFabType'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mcolormatchstdmodel->fnChangeColourms($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));    }}